/**
 * The 8-20 Hz "two maxima" detector, ported from `run_twomax` in
 * pipeline/probe_baseline.py.
 *
 * It is `butter(2, [8, 20])` forward-backward, then a five-point derivative
 * forward-backward, then a 120 ms moving average and peak picking. The
 * forward-backward passes are scipy's `filtfilt(padtype="odd")`, whose exact
 * edge extension matters: without it the first and last ~15 samples swing
 * wildly and produce spurious candidates at the segment boundaries.
 *
 * b, a and the filter's steady state (`lfilter_zi`) are generated by scipy and
 * shipped in filterCoeffs.json. Recomputing them here from a design formula
 * would be a second source of truth.
 */

import coeffs from "../filterCoeffs.json";
import { findPeaks, percentile } from "./math";

interface BaZi {
  b: number[];
  a: number[];
  zi: number[];
}

const C = coeffs as unknown as Record<string, unknown>;
const TWOMAX = C.twomax as BaZi;
const TWOMAX_DERIV = C.twomaxDeriv as BaZi;

/**
 * scipy's odd extension: reflect about the endpoint without repeating it.
 * ext = [2*x0 - x[n], ..., 2*x0 - x[1], x, 2*x[-1] - x[-2], ...].
 */
function oddExt(x: Float64Array, n: number): Float64Array {
  if (n < 1) return x;
  if (n > x.length - 1) {
    throw new Error(`odd extension length ${n} exceeds signal length ${x.length}`);
  }
  const out = new Float64Array(x.length + 2 * n);
  const x0 = x[0];
  for (let i = 0; i < n; i++) out[i] = 2 * x0 - x[n - i];
  out.set(x, n);
  const xl = x[x.length - 1];
  for (let i = 0; i < n; i++) {
    out[n + x.length + i] = 2 * xl - x[x.length - 2 - i];
  }
  return out;
}

/**
 * scipy.signal.lfilter for a single channel, transposed direct form II, with
 * an initial state vector. a[0] is assumed to be 1 (true for every filter in
 * filterCoeffs.json).
 */
function lfilter(x: Float64Array, b: number[], a: number[], zi: ArrayLike<number>): Float64Array {
  const n = x.length;
  const nz = zi.length;
  const y = new Float64Array(n);
  const z = new Float64Array(nz);
  for (let i = 0; i < nz; i++) z[i] = zi[i] as number;
  const b0 = b[0];
  for (let i = 0; i < n; i++) {
    const xi = x[i];
    const yi = b0 * xi + z[0];
    for (let k = 0; k < nz - 1; k++) {
      z[k] = (b[k + 1] ?? 0) * xi + z[k + 1] - (a[k + 1] ?? 0) * yi;
    }
    z[nz - 1] = (b[nz] ?? 0) * xi - (a[nz] ?? 0) * yi;
    y[i] = yi;
  }
  return y;
}

/** scipy.signal.filtfilt with padtype="odd". */
export function filtfiltOdd(x: Float64Array, f: BaZi, padlen?: number): Float64Array {
  const edge = padlen ?? 3 * Math.max(f.a.length, f.b.length);
  const ext = oddExt(x, edge);

  const ziF = f.zi.map((v) => v * ext[0]);
  let y = lfilter(ext, f.b, f.a, ziF);
  y.reverse();

  const ziB = f.zi.map((v) => v * y[0]);
  y = lfilter(y, f.b, f.a, ziB);
  y.reverse();

  return y.subarray(edge, y.length - edge).slice();
}

/** np.convolve(x, ones(m)/m, mode="same") via a prefix sum. */
function movingAverageSame(x: Float64Array, m: number): Float64Array {
  const n = x.length;
  const prefix = new Float64Array(n + 1);
  for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + x[i];
  const off = (m - 1) >> 1;
  const out = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    // out[i] = full[i + off]; full[t] sums x[j] for j in [t-m+1, t].
    const t = i + off;
    const lo = Math.max(0, t - m + 1);
    const hi = Math.min(n - 1, t);
    out[i] = (prefix[hi + 1] - prefix[lo]) / m;
  }
  return out;
}

/** run_twomax(sig, fs): candidate R peaks from an 8-20 Hz envelope. */
export function runTwomax(sig: ArrayLike<number>, fs = 250): Int32Array {
  const x = new Float64Array(sig.length);
  for (let i = 0; i < sig.length; i++) x[i] = sig[i] as number;

  const s = filtfiltOdd(x, TWOMAX);
  const dRaw = filtfiltOdd(s, TWOMAX_DERIV);
  const d = new Float64Array(dRaw.length);
  for (let i = 0; i < dRaw.length; i++) d[i] = Math.abs(dRaw[i]);

  const ma = Math.trunc(0.12 * fs);
  const integ = movingAverageSame(d, ma);
  const height = 0.3 * percentile(integ, 99);
  return findPeaks(integ, height, Math.trunc(0.25 * fs));
}
